	r=Packages.org.jsoup.Jsoup.parse(r)
	captcha = r.select(".captcha-text").text()
	java.log(captcha)
	java.ajax(`${source.key}/verify,{
		"body": "captcha=${captcha}&return_url=%2F",
		"method": "POST"
	}`)
	java.getStrResponse(java.initUrl())
} else result

